  "traits",
  "trait Shape {\n  area(Self) -> Int\n  name(Self) -> String\n}\n\ntrait Solid : Shape {\n  volume(Self, Int) -> Int\n}\n\nstruct Square {\n  side : Int\n}\n\nstruct Rect {\n  w : Int\n  h : Int\n}\n\nimpl Shape for Square with area(self) { self.side * self.side }\nimpl Shape for Square with name(self) { \"square\" }\nimpl Solid for Square with volume(self, depth) { self.area() * depth }\nimpl Shape for Rect with area(self) { self.w * self.h }\nimpl Shape for Rect with name(_) { \"rect\" }\n\nfn[S : Shape] describe(s : S) -> String {\n  \"\\{s.name()} with area \\{s.area()}\"\n}\n\nfn[S : Solid] describe_solid(s : S) -> String {\n  // Shape methods are available through the superclass\n  describe(s) + \", volume \\{s.volume(2)}\"\n}\n\nfn[T : Show] show_all(xs : Array[T]) -> String {\n  fn wrap(s : String) -> String { \"<\" + s + \">\" }\n  let mut out = \"\"\n  for x in xs {\n    out = out + wrap(x.to_string())\n  }\n  out\n}\n\nenum And[A : Prop, B : Prop] : Prop {\n  Conj(A, B)\n}\n\nlemma and_comm[A : Prop, B : Prop] : (And[A, B]) -> And[B, A] = proof {\n  intros p\n  destruct p\n  exact Conj(p_1, p_0)\n}\n\n// a two-argument (uncurried) function type\nlemma modus_ponens[A : Prop, B : Prop] : (A, (A) -> B) -> B = proof {\n  intros a f\n  apply f\n  exact a\n}\n\nlemma use_assume : forall n : Nat, plus(0, n) === n = proof {\n  intros n\n  assume h : plus(0, n) === n\n  exact h\n  rfl\n}\n\nfn main {\n  println(describe({ side: 3 }))\n  println(describe({ w: 2, h: 5 }))\n  println(describe_solid({ side: 2 }))\n  println(show_all([1, 2, 3]))\n}\n"
