  "mbt_types",
  "// `#mbt` types and traits translate trivially to MoonBit: the compiled\n// program uses the MoonBit enum `Tree[T]`, the struct `Point`, the trait\n// `Size` with real `impl`s, and `fn[T0 : Size]` bounds. `#mbt` functions\n// become public MoonBit functions of the same name (`pub fn total`, the\n// method `pub fn Tree::depth`, ...), callable from MoonBit code.\n\n#mbt\nenum Tree[T] {\n  Leaf\n  Node(Tree[T], T, Tree[T])\n}\n\n#mbt\nstruct Point {\n  x : Int\n  y : Int\n}\n\n#mbt\ntrait Size {\n  size(Self) -> Int\n  zero() -> Self\n}\n\nimpl Size for Int with size(self) { self }\nimpl Size for Int with zero() { 0 }\n\nimpl Size for Point with size(self) { self.x + self.y }\nimpl Size for Point with zero() { { x: 0, y: 0 } }\n\nimpl[T : Size] Size for Tree[T] with size(self) {\n  match self {\n    Leaf => 0\n    Node(l, x, r) => l.size() + x.size() + r.size()\n  }\n}\nimpl[T : Size] Size for Tree[T] with zero() { Leaf }\n\n#mbt\nfn[T : Size] total(xs : Tree[T]) -> Int {\n  xs.size()\n}\n\n#mbt\nfn[T] insert(t : Tree[T], x : T, lt~ : (T, T) -> Bool) -> Tree[T] {\n  match t {\n    Leaf => Node(Leaf, x, Leaf)\n    Node(l, y, r) =>\n      if lt(x, y) {\n        Node(insert(l, x, lt~), y, r)\n      } else {\n        Node(l, y, insert(r, x, lt~))\n      }\n  }\n}\n\nfn[T : Size] sum_zero() -> Int {\n  let z : T = Size::zero()\n  z.size()\n}\n\n#mbt\nfn[T] Tree::depth(self : Tree[T]) -> Int {\n  match self {\n    Leaf => 0\n    Node(l, _, r) => {\n      let a = l.depth()\n      let b = r.depth()\n      1 + (if a > b { a } else { b })\n    }\n  }\n}\n\n// `Option` is the MoonBit `Option` (`#mbt(\"Option\")` in the prelude)\n#mbt\nfn first_big(t : Tree[Int], n : Int) -> Int? {\n  match t {\n    Leaf => None\n    Node(l, x, r) =>\n      match first_big(l, n) {\n        Some(y) => Some(y)\n        None => if x > n { Some(x) } else { first_big(r, n) }\n      }\n  }\n}\n\n// native code calling `total` at concrete types: MoonBit resolves the impls\nfn sizes(t : Tree[Int], ps : Tree[Point]) -> Int {\n  total(t) * 100 + total(ps) + sum_zero[Point]()\n}\n\nfn main {\n  let mut t : Tree[Int] = Leaf\n  for i = 0; i < 6; i = i + 1 {\n    t = insert(t, (i * 7) % 10, lt=(a, b) => a < b)\n  }\n  println(total(t))\n  let ps : Tree[Point] = Node(Leaf, { x: 1, y: 2 }, Node(Leaf, { x: 3, y: 4 }, Leaf))\n  println(total(ps))\n  println(sum_zero[Point]())\n  println(sizes(t, ps))\n  println(first_big(t, 4))\n  println(first_big(t, 100))\n  println(t.depth())\n}\n"
