  "proofs",
  "// Proofs about natural numbers, lists and length-indexed vectors.\n\n// ---- Nat -----------------------------------------------------------------\n\nlemma plus_zero(n : Nat) -> n + 0 === n {\n  match n {\n    Z => Refl\n    S(k) => Id::cong(S, plus_zero(k))\n  }\n}\n\nlemma plus_succ(n : Nat, m : Nat) -> n + S(m) === S(n + m) {\n  match n {\n    Z => Refl\n    S(k) => Id::cong(S, plus_succ(k, m))\n  }\n}\n\nlemma plus_assoc(n : Nat, m : Nat, k : Nat) -> n + m + k === n + (m + k) {\n  match n {\n    Z => Refl\n    S(p) => Id::cong(S, plus_assoc(p, m, k))\n  }\n}\n\n// commutativity, with tactics\nlemma plus_comm : forall n m : Nat, n + m === m + n = proof {\n  intros n m\n  destruct n\n  rewrite plus_zero(m)\n  rfl\n  rewrite plus_succ(m, n_0)\n  rewrite plus_comm(n_0, m)\n  rfl\n}\n\n// ---- lists: the lemma from the language description ------------------------\n\nlemma append_nil[T](xs : List[T]) -> xs.append(Nil) === xs {\n  match xs {\n    Nil => Refl\n    Cons(x, rest) => Id::cong(r => List::Cons(x, r), append_nil(rest))\n  }\n}\n\nlemma append_assoc[T](xs : List[T], ys : List[T], zs : List[T]) -> xs.append(ys).append(zs) === xs.append(ys.append(zs)) {\n  match xs {\n    Nil => Refl\n    Cons(x, rest) => Id::cong(r => List::Cons(x, r), append_assoc(rest, ys, zs))\n  }\n}\n\nlemma reverse_append[T](xs : List[T], ys : List[T]) -> xs.append(ys).reverse() === ys.reverse().append(xs.reverse()) {\n  match xs {\n    Nil => Id::sym(append_nil(ys.reverse()))\n    Cons(x, rest) => {\n      let ih = Id::cong(r => r.append(Cons(x, Nil)), reverse_append(rest, ys))\n      Id::trans(ih, append_assoc(ys.reverse(), rest.reverse(), Cons(x, Nil)))\n    }\n  }\n}\n\nlemma reverse_reverse[T] : forall xs : List[T], xs.reverse().reverse() === xs = proof {\n  intros xs\n  destruct xs\n  rfl\n  rewrite reverse_append(xs_1.reverse(), Cons(xs_0, Nil))\n  rewrite reverse_reverse(xs_1)\n  rfl\n}\n\n// ---- vectors ---------------------------------------------------------------\n\nenum Vector[T] : Nat -> Type {\n  Nil : Vector[T](0)\n  Cons[n : Nat](T, Vector[T](n)) : Vector[T](S(n))\n}\n\nfn[T, n : Nat, m : Nat] Vector::append(self : Vector[T](n), ys : Vector[T](m)) -> Vector[T](n + m) {\n  match self {\n    Nil => ys\n    Cons(x, xs) => Cons(x, xs.append(ys))\n  }\n}\n\n// transport along an equation between lengths\nfn[T, a : Nat, b : Nat] cast(p : a === b, v : Vector[T](a)) -> Vector[T](b) {\n  match p {\n    Refl => v\n  }\n}\n\nlemma cast_cons[T, a : Nat, b : Nat](p : a === b, x : T, v : Vector[T](a)) -> cast(Id::cong(S, p), Vector::Cons(x, v)) === Vector::Cons(x, cast(p, v)) {\n  match p {\n    Refl => Refl\n  }\n}\n\nlemma vappend_assoc[T, n : Nat, m : Nat, k : Nat](xs : Vector[T](n), ys : Vector[T](m), zs : Vector[T](k)) -> cast(plus_assoc(n, m, k), xs.append(ys).append(zs)) === xs.append(ys.append(zs)) {\n  match xs {\n    Nil => Refl\n    Cons(x, rest) =>\n      Id::trans(\n        cast_cons(plus_assoc(_, m, k), x, rest.append(ys).append(zs)),\n        Id::cong(v => Vector::Cons(x, v), vappend_assoc(rest, ys, zs)),\n      )\n  }\n}\n\nfn[T, n : Nat] Vector::to_list(self : Vector[T](n)) -> List[T] {\n  match self {\n    Nil => List::Nil\n    Cons(x, xs) => List::Cons(x, xs.to_list())\n  }\n}\n\nfn main {\n  let v : Vector[Int](2) = Cons(1, Cons(2, Nil))\n  let w = cast(plus_assoc(2, 2, 2), v.append(v).append(v))\n  println(w.to_list())\n  let l : List[Int] = Cons(1, Cons(2, Cons(3, Nil)))\n  println(l.reverse().reverse())\n}\n"
