  "errors",
  "suberror DivError {\n  DivError(String)\n}\n\nfn div(a : Int, b : Int) -> Int raise DivError {\n  if b == 0 {\n    raise DivError(\"division by zero\")\n  }\n  a / b\n}\n\nfn sum_to(n : Int) -> Int {\n  let mut acc = 0\n  for i = 1; i <= n; i = i + 1 {\n    acc = acc + i\n  }\n  acc\n}\n\nfn find_first(xs : Array[Int], p : (Int) -> Bool) -> Int {\n  for x in xs {\n    if p(x) {\n      return x\n    }\n  }\n  -1\n}\n\nfn main {\n  let r = try div(10, 0) catch {\n    DivError(msg) => {\n      println(\"caught: \" + msg)\n      0\n    }\n  }\n  println(r)\n  println(try? div(10, 2))\n  println(sum_to(100))\n  println(find_first([1, 5, 8, 11], x => x % 2 == 0))\n  let mut i = 0\n  while true {\n    i = i + 1\n    if i > 5 { break }\n  }\n  println(\"i = \\{i}\")\n  let arr = Array::make(3, 0)\n  arr[1] = 42\n  for k in 0..<3 {\n    print(arr[k])\n    print(\" \")\n  }\n  println(\"\")\n}\n"
