 [
  "stlc",
  "// Safe indexing and a well-typed interpreter for the simply typed\n// lambda calculus: terms are indexed by their context and type, so `eval`\n// cannot go wrong.\n\nenum Vector[T] : Nat -> Type {\n  Nil : Vector[T](0)\n  Cons[n : Nat](T, Vector[T](n)) : Vector[T](S(n))\n}\n\nenum Fin : (Nat) -> Type {\n  FZ[n : Nat] : Fin(S(n))\n  FS[n : Nat](Fin(n)) : Fin(S(n))\n}\n\n// No case for Nil: Fin(0) is empty.\nfn[T, n : Nat] Vector::get(self : Vector[T](n), i : Fin(n)) -> T {\n  match (self, i) {\n    (Cons(x, _), FZ) => x\n    (Cons(_, xs), FS(j)) => xs.get(j)\n  }\n}\n\nfn[n : Nat] Fin::to_int(self : Fin(n)) -> Int {\n  match self {\n    FZ => 0\n    FS(j) => j.to_int() + 1\n  }\n}\n\n// ---- types and their meaning -------------------------------------------------\n\nenum Ty {\n  TInt\n  TBool\n  TArr(Ty, Ty)\n}\n\nfn Ty::interp(self : Ty) -> Type {\n  match self {\n    TInt => Int\n    TBool => Bool\n    TArr(a, b) => (a.interp()) -> b.interp()\n  }\n}\n\nenum Ctx {\n  Empty\n  Ext(Ctx, Ty)\n}\n\nenum Elem : (Ctx, Ty) -> Type {\n  Here[g : Ctx, t : Ty] : Elem(Ext(g, t), t)\n  There[g : Ctx, t : Ty, s : Ty](Elem(g, t)) : Elem(Ext(g, s), t)\n}\n\nenum Term : (Ctx, Ty) -> Type {\n  Var[g : Ctx, t : Ty](Elem(g, t)) : Term(g, t)\n  Lit[g : Ctx](Int) : Term(g, TInt)\n  Plus[g : Ctx](Term(g, TInt), Term(g, TInt)) : Term(g, TInt)\n  Leq[g : Ctx](Term(g, TInt), Term(g, TInt)) : Term(g, TBool)\n  Cond[g : Ctx, t : Ty](Term(g, TBool), Term(g, t), Term(g, t)) : Term(g, t)\n  Lam[g : Ctx, a : Ty, b : Ty](Term(Ext(g, a), b)) : Term(g, TArr(a, b))\n  App[g : Ctx, a : Ty, b : Ty](Term(g, TArr(a, b)), Term(g, a)) : Term(g, b)\n}\n\nenum Env : (Ctx) -> Type {\n  ENil : Env(Empty)\n  ECons[g : Ctx, t : Ty](Env(g), t.interp()) : Env(Ext(g, t))\n}\n\nfn[g : Ctx, t : Ty] Env::lookup(self : Env(g), e : Elem(g, t)) -> t.interp() {\n  match (self, e) {\n    (ECons(_, v), Here) => v\n    (ECons(rest, _), There(e2)) => rest.lookup(e2)\n  }\n}\n\nfn[g : Ctx, t : Ty] Term::eval(self : Term(g, t), env : Env(g)) -> t.interp() {\n  match self {\n    Var(e) => env.lookup(e)\n    Lit(n) => n\n    Plus(a, b) => a.eval(env) + b.eval(env)\n    Leq(a, b) => a.eval(env) <= b.eval(env)\n    Cond(c, x, y) => if c.eval(env) { x.eval(env) } else { y.eval(env) }\n    Lam(body) => x => body.eval(ECons(env, x))\n    App(f, a) => f.eval(env)(a.eval(env))\n  }\n}\n\n// The meaning of a closed term is computed at type-checking time.\nlemma two_plus_two : Plus(Lit(2), Lit(2)).eval(ENil) === 4 = Refl\n\nfn main {\n  let v : Vector[String](3) = Cons(\"a\", Cons(\"b\", Cons(\"c\", Nil)))\n  println(v.get(FS(FS(FZ))))\n\n  // (fn x => x + 1)(41)\n  let inc : Term(Empty, TArr(TInt, TInt)) = Lam(Plus(Var(Here), Lit(1)))\n  println(App(inc, Lit(41)).eval(ENil))\n\n  // K combinator\n  let k : Term(Empty, TArr(TInt, TArr(TInt, TInt))) = Lam(Lam(Var(There(Here))))\n  println(App(App(k, Lit(1)), Lit(2)).eval(ENil))\n\n  // max as a closed term, used from MoonBit++ as an ordinary function\n  let max : Term(Empty, TArr(TInt, TArr(TInt, TInt))) =\n    Lam(Lam(Cond(Leq(Var(There(Here)), Var(Here)), Var(Here), Var(There(Here)))))\n  let f = max.eval(ENil)\n  println(f(3)(7))\n}\n"
 ],
 [
  "struct_proof",
  "struct Vec[T, n : Nat] {\n  to_array : Array[T]\n  length_to_array : to_array.size() === n\n}\n\nfn[T] Vec::from_array(xs : Array[T]) -> Vec[T, xs.size()] {\n  { to_array: xs, length_to_array: Refl }\n}\n\nfn[T, n : Nat] Vec::get(self : Vec[T, n], i : Int) -> T {\n  self.to_array[i]\n}\n\nlemma plus_zero : forall n : Nat, plus(n, 0) === n = proof {\n  intros n\n  destruct n\n  rfl\n  rewrite plus_zero(n_0)\n  rfl\n}\n\nlemma plus_succ(n : Nat, m : Nat) -> plus(n, S(m)) === S(plus(n, m)) {\n  match n {\n    Z => Refl\n    S(k) => Id::cong(S, plus_succ(k, m))\n  }\n}\n\nfn main {\n  let v = Vec::from_array([1, 2, 3])\n  println(v.get(1))\n  println(v.to_array)\n}\n"
 ]
